from lib import Q
C='prep-coloring'
Q(C,'basic',"일반 네일 폴리시 컬러링의 순서로 알맞은 것은?","베이스 코트 → 컬러 2회 → 톱 코트",[("톱 코트 → 컬러 2회 → 베이스 코트","순서가 거꾸로입니다."),("컬러 2회 → 베이스 코트 → 톱 코트","베이스 코트는 맨 먼저 바릅니다."),("베이스 코트 → 톱 코트 → 컬러 2회","톱 코트는 맨 마지막에 바릅니다.")],"컬러링 = 베이스 → 컬러 2회 → 톱","컬러링은 **베이스 코트**로 손톱을 보호하고, **컬러를 2회** 얇게 바른 뒤, **톱 코트**로 광택과 보호막을 입힙니다.",5,["컬러링 순서"])
Q(C,'basic',"베이스 코트를 바르는 주된 목적은?","컬러가 손톱에 물드는 것을 막고 폴리시가 잘 붙게 한다",[("마지막에 광택을 더한다","톱 코트의 역할입니다."),("큐티클을 부드럽게 한다","큐티클 연화제나 오일의 역할입니다."),("폴리시를 지운다","리무버의 역할입니다.")],"베이스 코트 = 착색 방지 + 밀착","**베이스 코트**는 컬러의 색소가 손톱에 스며들어 누렇게 물드는 것을 막고 폴리시가 손톱에 잘 붙게 합니다.",5,["베이스 코트"])
Q(C,'basic',"컬러를 바른 뒤 마지막에 발라 광택을 주고 컬러가 벗겨지지 않게 보호하는 것은?","톱 코트",[("베이스 코트","컬러 전에 바르는 첫 코팅입니다."),("프라이머","인조 네일의 접착을 돕는 제품입니다."),("큐티클 리무버","큐티클을 부드럽게 하는 제품입니다.")],"마지막 광택·보호 = 톱 코트","**톱 코트**는 컬러 위에 발라 광택을 내고 컬러가 긁히거나 벗겨지는 것을 막습니다.",5,["톱 코트"])
Q(C,'intermediate',"폴리시를 바르기 전 손톱 표면의 유분기와 잔여물을 없애는 전 처리를 하는 이유는?","폴리시가 잘 밀착되어 들뜨거나 벗겨지지 않게 하려고",[("손톱을 더 빨리 자라게 하려고","손톱 성장과 관계없습니다."),("폴리시 색을 더 진하게 하려고","색의 진하기와는 관계없습니다."),("폴리시가 빨리 마르지 않게 하려고","건조 속도를 늦추려는 것이 아닙니다.")],"유분 제거 = 밀착력 향상","손톱 표면에 유분이나 잔여물이 남아 있으면 폴리시가 잘 붙지 않아 **들뜨고 벗겨지기 쉽습니다**. 그래서 컬러링 전에 유분과 잔여물을 깨끗이 닦아 냅니다.",4,["전 처리"])
Q(C,'intermediate',"젤 네일 폴리시 전 처리에서 자연 네일 표면의 광택을 가볍게 없애는 이유는?","표면을 약간 거칠게 하여 젤이 잘 붙게 하려고",[("손톱을 얇게 갈아 내 길이를 줄이려고","표면만 가볍게 정리하며 손톱을 얇게 갈아 내지 않습니다."),("손톱 색을 하얗게 만들려고","색과 관계없습니다."),("큐티클을 없애려고","큐티클 정리는 따로 합니다.")],"젤 전 처리 = 광택 가볍게 제거(버핑) → 밀착","젤 폴리시를 바르기 전 고운 파일이나 샌딩으로 손톱 표면의 **광택만 가볍게 없애** 젤이 잘 붙게 합니다. 지나치게 갈면 자연 네일이 얇아지고 상합니다. 그다음 분진과 유분을 닦아 냅니다.",4,["전 처리"])
Q(C,'advanced',"인조 네일 전 처리에서 프라이머를 바를 때의 주의 사항으로 가장 알맞은 것은?","자연 네일에만 소량 바르고 피부에 닿지 않게 한다",[("손톱과 큐티클 주변 피부에 넉넉히 바른다","프라이머는 피부를 자극할 수 있어 피부에 닿지 않게 합니다."),("인조 네일 위에 두껍게 여러 번 바른다","자연 네일에 소량만 바릅니다."),("바른 뒤 바로 손을 씻어 낸다","씻어 내면 접착을 도울 수 없습니다.")],"프라이머 = 자연 네일에만 소량, 피부 접촉 금지","**프라이머**는 자연 네일과 인조 네일 화장물의 접착을 돕는 제품으로, 산성 제품은 피부를 자극할 수 있습니다. **자연 네일에만 소량** 바르고 피부에 닿지 않게 합니다.",4,["전 처리","프라이머"])
Q(C,'basic',"프렌치 컬러링에 대한 설명으로 옳은 것은?","프리에지 부분에만 색을 칠해 스마일 라인을 만든다",[("손톱 전체를 한 가지 색으로 칠한다","풀 코트 컬러링의 설명입니다."),("손톱 위에서 아래로 색이 점점 옅어지게 칠한다","그러데이션 컬러링의 설명입니다."),("물 위에 폴리시를 떨어뜨려 무늬를 만든다","워터 마블 아트의 설명입니다.")],"프렌치 = 프리에지에만, 스마일 라인","**프렌치** 컬러링은 프리에지 부분에만 색을 칠해 반달 모양의 **스마일 라인**을 만드는 방법입니다. 좌우가 대칭이고 선이 선명해야 합니다.",5,["프렌치"])
Q(C,'intermediate',"프렌치보다 색을 칠하는 부분을 넓혀 네일 바디의 절반 정도 이상까지 스마일 라인을 내려 칠하는 컬러링은?","딥 프렌치",[("풀 코트","손톱 전체를 칠하는 방법입니다."),("그러데이션","색이 점점 옅어지게 하는 방법입니다."),("프리 월","손톱 양옆을 조금 남기고 칠하는 방법입니다.")],"딥 프렌치 = 스마일 라인을 깊게","**딥 프렌치**는 프렌치보다 스마일 라인을 깊게 내려 네일 바디의 절반 정도 이상까지 색을 칠하는 방법입니다.",4,["딥 프렌치"])
Q(C,'basic',"스펀지로 두드려 손톱 위에서 색이 점점 진해지거나 옅어지게 표현하는 컬러링은?","그러데이션",[("프렌치","프리에지에만 색을 칠합니다."),("풀 코트","손톱 전체를 한 가지 색으로 칠합니다."),("딥 프렌치","스마일 라인을 깊게 내려 칠합니다.")],"점점 옅어짐 = 그러데이션(스펀지)","**그러데이션**은 스펀지 등으로 두드려 색이 자연스럽게 점점 진해지거나 옅어지게 표현하는 방법입니다.",4,["그러데이션"])
Q(C,'basic',"손톱 전체를 빈틈없이 한 가지 색으로 칠하는 컬러링은?","풀 코트",[("프렌치","프리에지에만 칠합니다."),("그러데이션","색이 점점 옅어지게 칠합니다."),("딥 프렌치","스마일 라인을 깊게 내려 칠합니다.")],"손톱 전체 = 풀 코트","**풀 코트**는 손톱 전체를 한 가지 색으로 빈틈없이 칠하는 가장 기본적인 컬러링입니다.",3,["풀 코트"])

C='polish-art-finish'
Q(C,'basic',"젤 네일 폴리시를 굳히는(경화) 방법은?","UV 램프나 LED 램프에 비춘다",[("공기 중에 그대로 두어 말린다","일반 폴리시는 공기 중에서 마르지만 젤은 램프에 비춰야 굳습니다."),("찬물에 담가 굳힌다","물로 굳지 않습니다."),("드라이어의 뜨거운 바람을 쐰다","열풍으로 굳지 않습니다.")],"젤 경화 = UV·LED 램프","젤 폴리시는 공기 중에 두어도 마르지 않고 **UV 램프나 LED 램프**의 빛을 받아야 굳습니다. 이것을 **경화**라 합니다.",5,["젤 경화"])
Q(C,'intermediate',"젤을 경화한 뒤 표면에 남는 끈적한 미경화 젤을 닦아 내는 데 쓰는 제품은?","젤 클렌저",[("큐티클 오일","보습 제품으로 미경화 젤을 닦는 데 쓰지 않습니다."),("핸드크림","보습 제품입니다."),("베이스 코트","컬러 전에 바르는 제품입니다.")],"미경화 젤 제거 = 젤 클렌저","젤을 경화하면 표면에 끈적한 **미경화 젤**이 남을 수 있습니다. 이것은 **젤 클렌저**를 적신 솜이나 와이프로 닦아 내 마무리합니다.",4,["젤 마무리"])
Q(C,'intermediate',"색상환에서 빨강의 보색(서로 마주 보는 색)은?","청록",[("주황","빨강과 이웃한 유사색입니다."),("노랑","빨강의 보색이 아닙니다."),("자주","빨강과 가까운 색입니다.")],"빨강 ↔ 청록 보색","색상환에서 마주 보는 색을 **보색**이라 합니다. **빨강의 보색은 청록**입니다. 보색끼리 배색하면 서로를 또렷하게 돋보이게 합니다.",3,["색채"])
Q(C,'basic',"따뜻한 느낌을 주는 색(난색)으로만 짝지은 것은?","빨강, 주황, 노랑",[("파랑, 청록, 남색","차가운 느낌을 주는 한색입니다."),("흰색, 회색, 검정","색깔이 없는 무채색입니다."),("초록, 보라, 회색","중성색과 무채색입니다.")],"난색 = 빨강·주황·노랑","**빨강·주황·노랑**처럼 따뜻한 느낌을 주는 색을 **난색**, 파랑 계열처럼 차가운 느낌을 주는 색을 **한색**이라 합니다.",3,["색채"])
Q(C,'basic',"물 위에 여러 색의 폴리시를 떨어뜨려 무늬를 만든 뒤 손톱에 옮기는 아트 기법은?","워터 마블",[("그러데이션","스펀지로 색을 점점 옅게 하는 기법입니다."),("프렌치","프리에지에만 색을 칠하는 기법입니다."),("스톤 아트","작은 장식 돌을 붙이는 기법입니다.")],"물 위 무늬 옮기기 = 워터 마블","**워터 마블**은 물 위에 폴리시를 떨어뜨려 이쑤시개 등으로 무늬를 만든 뒤 손톱을 담가 무늬를 옮기는 기법입니다.",3,["폴리시 아트"])
Q(C,'basic',"끝이 둥근 구슬 모양으로 되어 있어 폴리시로 동그란 점을 찍을 때 쓰는 도구는?","도트 툴",[("니퍼","큐티클을 자르는 도구입니다."),("푸셔","큐티클을 밀어 올리는 도구입니다."),("클리퍼","손톱 길이를 자르는 도구입니다.")],"점 찍기 = 도트 툴","**도트 툴**은 끝이 둥근 구슬 모양이라 폴리시를 묻혀 크고 작은 점을 찍는 데 씁니다.",3,["아트 도구"])
Q(C,'intermediate',"인조 네일 마무리에서 표면의 파일 자국을 없애고 광택을 내는 순서로 알맞은 것은?","샌딩 블록으로 표면을 고르게 한 뒤 광택용 버퍼로 문질러 광을 낸다",[("광택용 버퍼로 먼저 광을 낸 뒤 거친 파일로 다듬는다","거친 파일을 나중에 쓰면 광택이 없어집니다."),("거친 80그릿 파일로만 마무리한다","거친 파일 자국이 남습니다."),("아세톤으로 표면을 닦아 광을 낸다","아세톤은 인조 네일을 녹입니다.")],"마무리 = 거친 것 → 고운 것 → 광택","인조 네일 마무리는 **거친 것에서 고운 것** 순서로 합니다. 샌딩 블록 등으로 표면의 파일 자국을 고르게 한 뒤 광택용 버퍼로 문질러 광을 냅니다.",4,["인조 네일 마무리"])
Q(C,'advanced',"젤을 두껍게 한 번에 올려 경화할 때 순간적으로 뜨거워지는 것을 줄이는 방법으로 가장 알맞은 것은?","젤을 얇게 여러 번 나누어 바르고 경화한다",[("젤을 더 두껍게 한 번에 올린다","두꺼울수록 경화할 때 열이 더 많이 납니다."),("램프 경화 시간을 줄여 덜 굳힌다","덜 굳으면 들뜸과 피부 자극의 원인이 됩니다."),("경화 전에 손을 뜨거운 물에 담근다","열감을 줄이는 방법이 아닙니다.")],"경화 열감 줄이기 = 얇게 여러 번","젤은 굳을 때 열이 나며, 두껍게 올리면 순간적으로 뜨거워질 수 있습니다. **얇게 여러 번** 나누어 바르고 경화하면 열감도 줄고 잘 굳습니다.",3,["젤 경화"])
